// Mirrors the DemoRequestPayload contract in elliot-web's services/elliotApi.ts.
// Required: name, company, email, industry, employees. website/automate optional.
const body = $input.first().json.body || {};

const required = ['name', 'company', 'email', 'industry', 'employees'];
for (const field of required) {
  if (!body[field] || String(body[field]).trim() === '') {
    throw new Error(`${field} is required`);
  }
}

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailPattern.test(body.email)) {
  throw new Error('email is not valid');
}

return [{
  json: {
    name: String(body.name).trim(),
    company: String(body.company).trim(),
    email: String(body.email).trim().toLowerCase(),
    website: body.website ? String(body.website).trim() : null,
    industry: String(body.industry).trim(),
    employees: String(body.employees).trim(),
    automate: body.automate ? String(body.automate).trim() : null,
  }
}];

