// Builds the raw RFC 2822 notification email (base64url-encoded) for Gmail's send API.
// Reuses the same message-building approach as workflow 15's 'Build Gmail Message'.
// TODO: set NOTIFY_TO to wherever the team wants these to land (an inbox, or a
// shared alias). Hardcoded here deliberately rather than per-request, since this
// always goes to the same place regardless of who submitted the form.
const d = $json;
const NOTIFY_TO = 'team@spiritustec.com';

const subject = `New demo request: ${d.company}`;
const body =
  `New demo request from the marketing site.\n\n` +
  `Name: ${d.name}\n` +
  `Company: ${d.company}\n` +
  `Email: ${d.email}\n` +
  `Website: ${d.website || '(not provided)'}\n` +
  `Industry: ${d.industry}\n` +
  `Employees: ${d.employees}\n` +
  `Wants to automate: ${d.automate || '(not provided)'}\n` +
  `Submitted: ${d.created_at}`;

const raw =
  `To: ${NOTIFY_TO}\r\n` +
  `Subject: ${subject}\r\n` +
  `Content-Type: text/plain; charset=UTF-8\r\n\r\n` +
  `${body}`;

const encoded = Buffer.from(raw).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

return [{ json: { ...d, raw_message: encoded } }];
